44	// 一次性提交全部字节。
45	std::string hash_whole(const std::vector<unsigned char>& data) {
46	    branchaudit::Sha256 sha;
47	    sha.update(data.data(), data.size());
48	    return hex_of(sha.final());
49	}
50	
51	// 按给定偏移分段提交（偏移为相对起点的累计切分点，0 与 data.size() 可省略）。
52	std::string hash_parts(const std::vector<unsigned char>& data,
53	                       const std::vector<std::size_t>& cuts) {
54	    branchaudit::Sha256 sha;
55	    std::size_t prev = 0;
56	    for (std::size_t cut : cuts) {
57	        sha.update(data.data() + prev, cut - prev);
58	        prev = cut;
59	    }
60	    sha.update(data.data() + prev, data.size() - prev);
61	    return hex_of(sha.final());
62	}
