68	// 确定性字节序列，覆盖 0x00 与 0xff。
69	std::vector<unsigned char> pattern(std::size_t n) {
70	    std::vector<unsigned char> v(n);
71	    for (std::size_t i = 0; i < n; ++i) {
72	        v[i] = static_cast<unsigned char>((i * 31 + 7) % 256);
73	    }
74	    return v;
75	}
