108	void test_byte_semantics() {
109	    // 普通文本
110	    expect_digest("plain text 'hello world'",
111	                  std::vector<unsigned char>{'h', 'e', 'l', 'l', 'o', ' ',
112	                                             'w', 'o', 'r', 'l', 'd'},
113	                  "b94d27b9934d3e08a52e52d7da7dabfac484efe37a5380ee9088f7ace2efcde9");
114	
115	    // 含零字节与高位字节（0xff）以及空格、换行的二进制内容
116	    expect_digest("binary with NUL/high/space/newline",
117	                  std::vector<unsigned char>{'a', 0x00, 'b', 0xff, ' ', 'c', '\n', 'd'},
118	                  "ae37f71921db5e6d58be22370d3f0cc73cd4fa8bcc327dccd8b881094bc03d7c");
119	
120	    // 0..255 全字节循环
121	    std::vector<unsigned char> ramp(256);
122	    for (int i = 0; i < 256; ++i) ramp[i] = static_cast<unsigned char>(i);
123	    expect_digest("byte ramp 0..255", ramp,
