141	
142	    // 只在单个内容字节上不同：c vs d
143	    expect_digest("single byte diff: abc",
144	                  std::vector<unsigned char>{'a', 'b', 'c'},
145	                  "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
