169	// ---- 增量接口：一次提交与任意分段必须一致 ---------------------------------
170	
171	void test_incremental_splits() {
172	    const std::size_t sizes[] = {0, 1, 2, 3, 55, 56, 63, 64, 65, 66,
173	                                 127, 128, 129, 200, 255, 256, 257};
174	    for (std::size_t n : sizes) {
175	        const std::vector<unsigned char> data = pattern(n);
176	        const std::string whole = hash_whole(data);
177	        // 每个切分点都试：含空段、恰好在 64 字节边界上、把边界两侧拆开。
178	        for (std::size_t cut = 0; cut <= n; ++cut) {
179	            check(hash_parts(data, {cut}) == whole,
180	                  "2-way split n=" + std::to_string(n) + " cut=" + std::to_string(cut));
181	        }
182	    }
183	
184	    // 较大输入上围绕分组边界的三分段组合。
185	    {
186	        const std::size_t n = 200;
187	        const std::vector<unsigned char> data = pattern(n);
188	        const std::string whole = hash_whole(data);
189	        const std::size_t points[] = {0, 1, 7, 55, 56, 63, 64, 65,
190	                                      127, 128, 129, 135, 199, 200};
191	        for (std::size_t c1 : points) {
192	            for (std::size_t c2 : points) {
193	                if (c1 > c2) continue;
194	                check(hash_parts(data, {c1, c2}) == whole,
195	                      "3-way split 200 @ " + std::to_string(c1) + "," +
196	                      std::to_string(c2));
197	            }
198	        }
199	    }
200	
201	    // 手工构造的对抗性分段：边界两侧逐字节拆开，缓冲区跨多次 update 填满。
202	    {
203	        const std::vector<unsigned char> data = pattern(300);
204	        const std::string whole = hash_whole(data);
205	        const std::size_t plans[][5] = {
206	            {63, 64, 64, 65, 44},   // 300 = 63+64+64+65+44
207	            {1, 64, 64, 64, 107},   // 300 = 1+64*3+107
208	            {56, 8, 56, 8, 172},
209	            {55, 1, 55, 1, 188},
210	        };
211	        for (const auto& plan : plans) {
212	            branchaudit::Sha256 sha;
213	            std::size_t off = 0;
214	            for (std::size_t len : plan) {
215	                sha.update(data.data() + off, len);
216	                off += len;
217	            }
218	            check(off == 300 && hex_of(sha.final()) == whole,
219	                  "adversarial segmented update");
220	        }
221	    }
222	}
