228	struct TempArea {
229	    fs::path root;
230	    explicit TempArea(const std::string& tag) {
231	        const auto cwd_hash = std::hash<fs::path>{}(fs::current_path());
232	        root = fs::temp_directory_path() /
233	               ("branchaudit_test_" + tag + "_" +
234	                std::to_string(static_cast<std::uint64_t>(cwd_hash)));
235	        fs::remove_all(root);
236	        fs::create_directories(root);
237	    }
238	    ~TempArea() { std::error_code ec; fs::remove_all(root, ec); }
239	};
