241	void write_file(const fs::path& p, const std::vector<unsigned char>& bytes) {
242	    fs::create_directories(p.parent_path());
243	    std::ofstream out(p, std::ios::binary | std::ios::trunc);
244	    out.write(reinterpret_cast<const char*>(bytes.data()),
245	              static_cast<std::streamsize>(bytes.size()));
246	    check(static_cast<bool>(out), std::string("write fixture ") + p.string());
247	}
