249	// 调用库接口期间截获标准输出/错误：库只返回结果，不自行打印。
250	std::pair<std::string, std::string> silent_file_hash(const fs::path& p,
251	                                                     branchaudit::FileHashResult* out) {
252	    std::stringstream cap_out, cap_err;
253	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
254	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
255	    *out = branchaudit::sha256_file(p);
256	    std::cout.rdbuf(old_out);
257	    std::cerr.rdbuf(old_err);
258	    return {cap_out.str(), cap_err.str()};
259	}
