261	void test_file_hashing() {
262	    TempArea tmp("file");
263	
264	    struct Case {
265	        std::string name;
266	        std::vector<unsigned char> bytes;
267	        std::string expected;  // sha256sum / OpenSSL 独立结果
268	    };
269	    const std::vector<unsigned char> binary = {'a', 0x00, 'b', 0xff, ' ',
270	                                               'c', '\n', 'd'};
271	    std::vector<Case> cases = {
272	        {"empty.bin", {},
273	         "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},
274	        {"text.txt",
275	         {'h', 'e', 'l', 'l', 'o', ' ', 'w', 'o', 'r', 'l', 'd', '\n'},
276	         ""},  // 下方用 sha256sum 风格常量填充
277	        {"binary.bin", binary,
278	         "ae37f71921db5e6d58be22370d3f0cc73cd4fa8bcc327dccd8b881094bc03d7c"},
279	        {"bound55.bin", fill_a(55),
280	         "9f4390f8d30c2dd92ec9f095b65e2b9ae9b0a925a5258e241c9f1e910f734318"},
281	        {"bound56.bin", fill_a(56),
282	         "b35439a4ac6f0948b6d6f9e3c6af0f5f590ce20f1bde7090ef7970686ec6738a"},
283	        {"bound63.bin", fill_a(63),
284	         "7d3e74a05d7db15bce4ad9ec0658ea98e3f06eeecf16b4c6fff2da457ddc2f34"},
285	        {"bound64.bin", fill_a(64),
286	         "ffe054fe7ae0cb6dc65c3af9b61d5209f439851db43d0ba5997337df154668eb"},
287	        {"bound65.bin", fill_a(65),
288	         "635361c48bb9eab14198e76ea8ab7f1a41685d6ad62aa9146d301d4f17eb0ae0"},
289	        // 超过 64KiB 且不是 64KiB 整数倍：尾部不能被遗漏。
290	        {"large65537.bin", fill_a(64 * 1024 + 1),
291	         "008ffc88d3c96a9f307524eb361e47c5222a887fc45fa0c1fb8d429c5c23b430"},
292	        {"large131073.bin", fill_a(128 * 1024 + 1),
293	         "7e009ea4ef882e385b3c0bcbbfa8d009bb0a633bdd764415c09182ee0e75da73"},
294	        {"large200000.bin", fill_a(200000),
295	         "2287d207f24a941ff3b56c04c8a25ad56b63e3023207b3bb5b4ac0c9869d74be"},
296	    };
297	    // "hello world\n" 的独立标准结果。
298	    cases[1].expected =
299	        "a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447";
300	
301	    std::string same_bytes_digest;
302	    for (std::size_t i = 0; i < cases.size(); ++i) {
303	        const auto& c = cases[i];
304	        const fs::path p = tmp.root / c.name;
305	        write_file(p, c.bytes);
306	
307	        branchaudit::FileHashResult r;
308	        auto [cout_text, cerr_text] = silent_file_hash(p, &r);
309	        check(r.ok(), std::string("file hash ok: ") + c.name);
310	        check(cout_text.empty() && cerr_text.empty(),
311	              std::string("library prints nothing: ") + c.name);
312	        check(r.digest.size() == 32, std::string("digest is 32 bytes: ") + c.name);
313	        check(hex_of(r.digest) == c.expected,
314	              std::string("file digest matches independent standard: ") + c.name);
315	        check(hex_of(r.digest) == hash_whole(c.bytes),
316	              std::string("file digest matches incremental API: ") + c.name);
317	        if (c.name == "binary.bin") same_bytes_digest = hex_of(r.digest);
318	    }
319	
320	    // 同样字节放在不同文件名/目录下必须同一摘要，路径文字不混入。
321	    const std::vector<unsigned char>& shared_bytes = cases[2].bytes;
322	    const fs::path alt_paths[] = {
323	        tmp.root / "copy.bin",
324	        tmp.root / "sub dir" / "another name.dat",
325	        tmp.root / "目录 一" / "文件 二.bin",
326	    };
327	    for (const auto& p : alt_paths) {
328	        write_file(p, shared_bytes);
329	        branchaudit::FileHashResult r;
330	        auto captured = silent_file_hash(p, &r);
331	        check(r.ok() && hex_of(r.digest) == same_bytes_digest,
332	              std::string("same bytes same digest regardless of path: ") + p.string());
333	        check(captured.first.empty() && captured.second.empty(),
334	              std::string("no printing for path: ") + p.string());
335	    }
336	
337	    // 路径含空格或中文：完整路径必须准确定位。
338	    const fs::path spaced = tmp.root / "spa ce dir" / "na me.bin";
339	    write_file(spaced, binary);
340	    {
341	        branchaudit::FileHashResult r;
342	        auto captured = silent_file_hash(spaced, &r);
343	        check(r.ok() && hex_of(r.digest) == same_bytes_digest,
344	              "path with spaces locates file");
345	        check(captured.first.empty() && captured.second.empty(),
346	              "path with spaces: no printing");
347	    }
348	    const fs::path chinese =
349	        tmp.root / "中文目录" / "摘要文件 数据.bin";
350	    write_file(chinese, fill_a(65));
351	    {
352	        branchaudit::FileHashResult r;
353	        auto captured = silent_file_hash(chinese, &r);
354	        check(r.ok() &&
355	                  hex_of(r.digest) ==
356	                      "635361c48bb9eab14198e76ea8ab7f1a41685d6ad62aa9146d301d4f17eb0ae0",
357	              "Chinese path locates file; path text not mixed into digest");
358	        check(captured.first.empty() && captured.second.empty(),
359	              "Chinese path: no printing");
360	    }
361	
362	    // 相对路径同样按完整路径定位。
363	    const fs::path rel_dir = tmp.root / "rel 目录";
364	    fs::create_directories(rel_dir);
365	    const fs::path rel_name = "r.bin";
366	    write_file(rel_dir / rel_name, binary);
367	    const fs::path old_cwd = fs::current_path();
368	    fs::current_path(rel_dir);
369	    branchaudit::FileHashResult rel_result;
370	    auto rel_captured = silent_file_hash(rel_name, &rel_result);
371	    fs::current_path(old_cwd);
372	    check(rel_result.ok() && hex_of(rel_result.digest) == same_bytes_digest,
373	          "relative path resolved from current directory");
374	    check(rel_captured.first.empty() && rel_captured.second.empty(),
375	          "relative path: no printing");
376	}
