378	// ---- 文件失败行为 ---------------------------------------------------------
379	
380	void test_file_failures() {
381	    TempArea tmp("fail");
382	
383	    // 路径不存在
384	    const fs::path missing = tmp.root / "does not exist 缺失.bin";
385	    {
386	        branchaudit::FileHashResult r;
387	        auto captured = silent_file_hash(missing, &r);
388	        check(!r.ok(), "nonexistent path: failure result");
389	        check(!r.error.empty(), "nonexistent path: error states reason");
390	        check(r.error.find(missing.string()) != std::string::npos,
391	              "nonexistent path: error names failed path");
392	        check(r.error.size() > missing.string().size() + 2,
393	              "nonexistent path: error gives reason beyond the path");
394	        check(captured.first.empty() && captured.second.empty(),
395	              "nonexistent path: library does not print");
396	    }
397	
398	    // 路径指向目录
399	    const fs::path dir = tmp.root / "a dir 目录";
400	    fs::create_directories(dir);
401	    {
402	        branchaudit::FileHashResult r;
403	        auto captured = silent_file_hash(dir, &r);
404	        check(!r.ok(), "directory path: failure result");
405	        check(!r.error.empty(), "directory path: error states reason");
406	        check(r.error.find(dir.string()) != std::string::npos,
407	              "directory path: error names failed path");
408	        check(r.error.find("directory") != std::string::npos,
409	              "directory path: error explains it is a directory");
410	        check(captured.first.empty() && captured.second.empty(),
411	              "directory path: library does not print");
412	    }
413	}
