415	// ---- to_hex 格式 ----------------------------------------------------------
416	
417	void test_hex_format() {
418	    branchaudit::Sha256 sha;
419	    const auto digest = sha.final();  // 空输入摘要
420	    const std::string hex = branchaudit::to_hex(digest);
421	    check(hex.size() == 64, "to_hex returns 64 characters");
422	    bool lowercase = true;
423	    for (char ch : hex) {
424	        const bool ok_digit = (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f');
425	        if (!ok_digit) lowercase = false;
426	    }
427	    check(lowercase, "to_hex is lowercase hexadecimal");
428	    check(hex == "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
429	          "to_hex of empty digest matches standard");
430	}
431	
432	}  // namespace
433	
434	int main() {
435	    test_standard_vectors();
436	    test_byte_semantics();
437	    test_boundary_lengths();
438	    test_incremental_splits();
439	    test_file_hashing();
440	    test_file_failures();
441	    test_hex_format();
442	
443	    if (g_failures == 0) {
444	        std::cout << "all " << g_checks << " sha256 regression checks passed\n";
445	        return 0;
446	    }
447	    std::cerr << g_failures << " of " << g_checks << " checks failed\n";
448	    return 1;
449	}
