#include "filehash.h"

#include <cerrno>
#include <cstring>
#include <fstream>
#include <system_error>
#include <vector>

namespace branchaudit {

namespace {

// 流式打开并读取 path，计算 SHA-256(prefix_byte || 文件全部原始字节)。
// 固定大小缓冲区，内存占用不随文件长度增长。
// 失败时返回的 error 非空，说明失败的路径和原因。
FileHashResult hash_file_prefixed(const std::filesystem::path& path,
                                  unsigned char prefix_byte) {
    FileHashResult result;

    std::error_code ec;
    if (std::filesystem::is_directory(path, ec)) {
        result.error = path.string() + ": is a directory";
        return result;
    }

    errno = 0;
    std::ifstream in(path, std::ios::binary);
    if (!in.is_open()) {
        const int saved_errno = errno;
        result.error = path.string() + ": " +
                       (saved_errno != 0
                            ? std::strerror(saved_errno)
                            : "cannot open file");
        return result;
    }

    Sha256 sha;
    sha.update(&prefix_byte, 1);
    // 固定大小缓冲区流式读取，内存占用不随文件长度增长。
    char buffer[64 * 1024];
    while (in) {
        in.read(buffer, sizeof(buffer));
        const std::streamsize count = in.gcount();
        if (count > 0) {
            sha.update(reinterpret_cast<const unsigned char*>(buffer),
                       static_cast<std::size_t>(count));
        }
    }
    if (in.bad()) {
        const int saved_errno = errno;
        result.error = path.string() + ": read error" +
                       (saved_errno != 0
                            ? std::string(": ") + std::strerror(saved_errno)
                            : std::string());
        return result;
    }

    result.digest = sha.final();
    return result;
}

// 父节点摘要：SHA-256(0x01 || 左摘要原始字节 || 右摘要原始字节)。
Digest hash_parent(const Digest& left, const Digest& right) {
    static constexpr unsigned char kParentPrefix = 0x01;
    Sha256 sha;
    sha.update(&kParentPrefix, 1);
    sha.update(left.data(), left.size());
    sha.update(right.data(), right.size());
    return sha.final();
}

}  // namespace

FileHashResult sha256_file(const std::filesystem::path& path) {
    // 普通文件摘要没有域分隔前缀；历史接口与标准 sha256sum 完全一致。
    FileHashResult result;

    std::error_code ec;
    if (std::filesystem::is_directory(path, ec)) {
        result.error = path.string() + ": is a directory";
        return result;
    }

    errno = 0;
    std::ifstream in(path, std::ios::binary);
    if (!in.is_open()) {
        const int saved_errno = errno;
        result.error = path.string() + ": " +
                       (saved_errno != 0
                            ? std::strerror(saved_errno)
                            : "cannot open file");
        return result;
    }

    Sha256 sha;
    // 固定大小缓冲区流式读取，内存占用不随文件长度增长。
    char buffer[64 * 1024];
    while (in) {
        in.read(buffer, sizeof(buffer));
        const std::streamsize count = in.gcount();
        if (count > 0) {
            sha.update(reinterpret_cast<const unsigned char*>(buffer),
                       static_cast<std::size_t>(count));
        }
    }
    if (in.bad()) {
        const int saved_errno = errno;
        result.error = path.string() + ": read error" +
                       (saved_errno != 0
                            ? std::string(": ") + std::strerror(saved_errno)
                            : std::string());
        return result;
    }

    result.digest = sha.final();
    return result;
}

MerkleRootResult merkle_root(const std::vector<std::filesystem::path>& paths) {
    MerkleRootResult result;

    // 先按命令行顺序计算全部叶子；任一文件失败则整批失败，绝不产出部分根。
    static constexpr unsigned char kLeafPrefix = 0x00;
    std::vector<Digest> level;
    level.reserve(paths.size());
    for (const auto& path : paths) {
        FileHashResult leaf = hash_file_prefixed(path, kLeafPrefix);
        if (!leaf.ok()) {
            result.error = std::move(leaf.error);
            return result;
        }
        level.push_back(leaf.digest);
    }

    if (level.empty()) {
        // 空批次：对空字节序列求 SHA-256，区别于单传一个空文件的叶子。
        Sha256 sha;
        result.digest = sha.final();
        return result;
    }

    // 每层相邻节点先左后右配对；落单节点的摘要原样上浮，不复制不补零。
    while (level.size() > 1) {
        std::vector<Digest> next;
        next.reserve((level.size() + 1) / 2);
        for (std::size_t i = 0; i < level.size(); i += 2) {
            if (i + 1 < level.size()) {
                next.push_back(hash_parent(level[i], level[i + 1]));
            } else {
                next.push_back(level[i]);
            }
        }
        level = std::move(next);
    }

    result.digest = level.front();
    return result;
}

std::string to_hex(const Digest& digest) {
    static constexpr char kHex[] = "0123456789abcdef";
    std::string out;
    out.reserve(digest.size() * 2);
    for (std::uint8_t byte : digest) {
        out.push_back(kHex[byte >> 4]);
        out.push_back(kHex[byte & 0x0f]);
    }
    return out;
}

}  // namespace branchaudit

